        requestedModel: this.model,
        appliedModel: null,
        startedAt: startedAt.toISOString(),
        finishedAt: new Date().toISOString(),
        latencyMs: Date.now() - startedMs,
        exitCode: error.code == null ? null : error.code,
        termination: 'auth_check_failed',
        stoppedBecause: responseStopReason({ termination: 'auth_check_failed', providerError: error.message }),
        parseStatus: 'request_failed',
        usage: null,
        rawResponse: stdout,
        rawError: stderr,
        providerFrames: [],
        toolsAvailable: [],
        executableTrust: this.executableTrust,
      };
      throw error;
    }
    try {
      this.authStatus = parseClaudeAuthStatus(stdout);
    } catch (error) {
      error.providerMetadata = {
        provider: this.providerName,
        requestedModel: this.model,
        appliedModel: null,
        startedAt: startedAt.toISOString(),
        finishedAt: new Date().toISOString(),
        latencyMs: Date.now() - startedMs,
        exitCode: 0,
        termination: 'auth_check_failed',
        stoppedBecause: responseStopReason({ termination: 'auth_check_failed', providerError: error.message }),
