function buildRunLedgerEntry({
  repoRoot,
  query,
  opts = {},
  result = null,
  error = null,
  startedAt,
  finishedAt = new Date(),
  autoBlastRadius = null,
  evidenceSources = [],
  inputProvenance = null,
} = {}) {
  const startedIso = isoTimestamp(startedAt || finishedAt);
  const finishedIso = isoTimestamp(finishedAt);
  const verdict = classifyMercuryVerdict({ result, error, autoBlastRadius });
  const repoState = readRepoState(repoRoot);
  const telemetry = result && result.toolTelemetry ? result.toolTelemetry : {};
  const reviewSummary = buildReviewLedgerSummary(result && (result.adversarialReview || result.consensus));
  const answerQualityFlags = result && result.answerQuality && Array.isArray(result.answerQuality.flags)
    ? result.answerQuality.flags
    : [];
  const answerQualityEvidence = result && result.answerQuality && Array.isArray(result.answerQuality.evidence)
    ? result.answerQuality.evidence
    : [];
  const suppliedEvidence = result && Array.isArray(result.evidenceSources)
    ? result.evidenceSources
    : evidenceSources;
  const promptProvenance = (result && result.inputProvenance)
    || inputProvenance
    || buildPromptProvenance(query, suppliedEvidence);
  const reviewQuarantines = collectReviewQuarantines(result);
  const candidateSet = result && result.candidateSet ? result.candidateSet : null;
  const attemptGroups = providerAttemptGroups(result);
  const runAccounting = sumSeatAccounting(attemptGroups);

  const entry = sanitizeForLedger({
    schema_version: 2,
    receipt_type: 'bridge_run',
    work_id: opts.workId || null,
    run_id: `${finishedIso.replace(/[:.]/g, '-')}-${hashText(`${repoState.head_sha}:${query}:${startedIso}`).slice(0, 12)}`,
    created_at: finishedIso,
    started_at: startedIso,
    branch: repoState.branch,
    head_sha: repoState.head_sha,
    dirty_status_summary: repoState.dirty_status_summary,
    prompt_hash: hashText(query),
    prompt_excerpt: truncateText(redactSensitiveText(query), PROMPT_EXCERPT_MAX),
    prompt_provenance: promptProvenance,
    attack_scope: opts.attackScope || 'agentic_query',
    source_refs: {
      current_change_evidence_bundle: autoBlastRadius && autoBlastRadius.evidenceBundle
        ? autoBlastRadius.evidenceBundle : null,
      supplied_evidence: promptProvenance.supplied_sources || [],
      auto_blast_radius_source: autoBlastRadius ? autoBlastRadius.source : null,
      auto_blast_radius_files: autoBlastRadius && Array.isArray(autoBlastRadius.meta)
        ? autoBlastRadius.meta.map((entry) => ({
          file: entry.file,
          callerCount: entry.callerCount,
          riskLevel: entry.riskLevel,
        }))
        : [],
      auto_blast_radius_errors: autoBlastRadius && Array.isArray(autoBlastRadius.errors)
        ? autoBlastRadius.errors
        : [],
      changed_files: autoBlastRadius && Array.isArray(autoBlastRadius.changedFiles)
        ? autoBlastRadius.changedFiles
        : [],
      changed_file_count: autoBlastRadius && Number.isInteger(autoBlastRadius.changedFileCount)
        ? autoBlastRadius.changedFileCount
        : 0,
      reference_names: autoBlastRadius && Array.isArray(autoBlastRadius.referenceNames)
        ? autoBlastRadius.referenceNames
        : [],
      reference_scans: autoBlastRadius && Array.isArray(autoBlastRadius.referenceScans)
        ? autoBlastRadius.referenceScans
        : [],
    },
    options: {
      retrievalMode: opts.retrievalMode || null,
      topK: opts.topK == null ? null : opts.topK,
      maxIterations: opts.maxIterations == null ? null : opts.maxIterations,
      decisionSteerIteration: opts.decisionSteerIteration == null ? null : opts.decisionSteerIteration,
      decisionSteerSentAt: result && result.decisionSteerSentAt != null
        ? result.decisionSteerSentAt
        : null,
      maxTokens: opts.maxTokens == null ? null : opts.maxTokens,
      captureTrace: opts.captureTrace === true,
      noTools: opts.noTools === true,
      reviewers: result && result.reviewerPanel ? result.reviewerPanel.selected : null,
    },
    tools_invoked: compactToolStats(telemetry),
    tools_available: Array.isArray(result && result.toolsAvailable) ? result.toolsAvailable : [],
    files_opened: Array.isArray(telemetry.filesOpened) ? telemetry.filesOpened : [],
    file_reads: Array.isArray(telemetry.fileReads) ? telemetry.fileReads : [],
    run_check_artifacts: Array.isArray(telemetry.runCheckArtifacts) ? telemetry.runCheckArtifacts : [],
    run_checks: Array.isArray(telemetry.runChecks) ? telemetry.runChecks : [],
    answer_quality: answerQualityFlags,
    answer_quality_evidence: answerQualityEvidence,
    candidate_set: candidateSet ? {
      coverage: candidateSet.coverage || null,
      claim_inventory: Array.isArray(candidateSet.claimInventory) ? candidateSet.claimInventory : [],
      content: redactSensitiveText(candidateSet.content || ''),
      captured_at_iteration: candidateSet.capturedAtIteration,
      revised_at_iteration: candidateSet.revisedAtIteration || null,
      revisions: candidateSet.revisions || [],
      files_mechanically_opened: Array.isArray(candidateSet.filesMechanicallyOpened)
        ? candidateSet.filesMechanicallyOpened
        : [],
      file_read_receipts: Array.isArray(candidateSet.fileReadReceipts)
        ? candidateSet.fileReadReceipts
        : [],
      claimed_file_citations: Array.isArray(candidateSet.claimedFileCitations)
        ? candidateSet.claimedFileCitations
        : [],
      final_answer_citations: Array.isArray(candidateSet.finalAnswerCitations)
        ? candidateSet.finalAnswerCitations
        : [],
      answer_citations_subset: candidateSet.answerCitationsSubset === true,
