        ? candidateSet.citationsNotInCandidateSet
        : [],
      candidate_sources: Array.isArray(candidateSet.candidateSources)
        ? candidateSet.candidateSources.map(candidateSourceLedgerReceipt)
        : [],
    } : null,
    review_quarantines: reviewQuarantines,
    sharded_review: shardedReviewLedgerReceipt(result && result.shardedReview),
    review_scope: autoBlastRadius && autoBlastRadius.reviewTarget || null,
    adversarial_review: reviewSummary,
    consensus: reviewSummary,
    reviewer_panel: result && result.reviewerPanel ? panelSeatLedger(result.reviewerPanel, result) : null,
    doctrine_review: result && result.doctrineReview ? result.doctrineReview : null,
    stages: {
      mercury: result ? {
        provider_attempts: Array.isArray(result.providerAttempts) ? result.providerAttempts : [],
        ...seatReceiptFields(
          result.answer ? redactSensitiveText(result.answer) : null,
          Array.isArray(result.providerAttempts) ? result.providerAttempts : [],
          result.termination || null
        ),
        tools_available: Array.isArray(result.toolsAvailable) ? result.toolsAvailable : [],
        tools_invoked: compactToolStats(telemetry),
        files_mechanically_opened: Array.isArray(telemetry.filesOpened) ? telemetry.filesOpened : [],
        repo_adjudication: { status: 'pending', authority: 'live_repo_required' },
      } : null,
      challenger: reviewSummary,
      tie_breaker: reviewSummary && reviewSummary.final_review ? reviewSummary.final_review : null,
    },
    termination: result ? result.termination : null,
    iterations: result ? result.iterations : null,
    latency_ms: result ? result.totalLatencyMs : null,
    verdict,
    error: error ? {
      name: error.name || 'Error',
      message: error.message || String(error),
    } : null,
    answer_excerpt: result && result.answer
      ? truncateText(redactSensitiveText(result.answer), ANSWER_EXCERPT_MAX)
      : null,
    run_tokens: runAccounting.run_tokens,
    run_cost: runAccounting.run_cost,
  });
  return sanitizeForLedger({
    ...entry,
    ...rollingCostReceipt({
      repoRoot,
      entry,
    }),
  });
}

function buildDirectQuestionLedgerEntry({
  repoRoot,
  prompt,
  promptSource = null,
  contextSources = [],
  systemPrompt,
  providerId,
  transportProvider,
  requestedModel,
  attempts = [],
  answer = null,
  metadata = {},
  toolTelemetry = {},
  toolsAvailable = [],
  iterations = null,
  iterationLimit = null,
  decisionSteerIteration = null,
  decisionSteerSentAt = null,
  termination = null,
  startedAt = new Date(),
  finishedAt = new Date(),
  error = null,
} = {}) {
  if (!repoRoot) throw new Error('repoRoot is required');
  if (typeof prompt !== 'string' || prompt.trim() === '') throw new Error('direct question prompt is required');
  if (typeof systemPrompt !== 'string' || systemPrompt.trim() === '') throw new Error('direct question system prompt is required');
  if (!providerId || !transportProvider || !requestedModel) {
    throw new Error('direct question provider identity is required');
  }
  const startedIso = isoTimestamp(startedAt);
  const finishedIso = isoTimestamp(finishedAt);
  const repoState = readRepoState(repoRoot);
  const accounting = sumAttemptAccounting(attempts);
  const entry = sanitizeForLedger({
    schema_version: 2,
    receipt_type: 'direct_model_question',
    run_id: `${finishedIso.replace(/[:.]/g, '-')}-${hashText(`${repoState.head_sha}:${providerId}:${prompt}:${startedIso}`).slice(0, 12)}`,
    created_at: finishedIso,
    started_at: startedIso,
    branch: repoState.branch,
    head_sha: repoState.head_sha,
    dirty_status_summary: repoState.dirty_status_summary,
    mode: 'direct',
    selected_provider: providerId,
    transport_provider: transportProvider,
    requested_model: requestedModel,
    applied_model: metadata.appliedModel || null,
    prompt_hash: hashText(prompt),
    prompt_excerpt: truncateText(redactSensitiveText(prompt), PROMPT_EXCERPT_MAX),
    prompt_source: promptSource,
    context_sources: contextSources,
    prompt_provenance: buildPromptProvenance(prompt),
    system_prompt: redactSensitiveText(systemPrompt),
    system_prompt_hash: hashText(systemPrompt),
    request_input_hash: hashText(JSON.stringify({ system: systemPrompt, user: prompt })),
    adversarial_pipeline_entered: false,
    reviewer_panel: null,
    doctrine_review: null,
    tools_available: toolsAvailable,
    tools_invoked: compactToolStats(toolTelemetry),
    files_opened: Array.isArray(toolTelemetry.filesOpened) ? toolTelemetry.filesOpened : [],
    file_reads: Array.isArray(toolTelemetry.fileReads) ? toolTelemetry.fileReads : [],
    run_check_artifacts: Array.isArray(toolTelemetry.runCheckArtifacts) ? toolTelemetry.runCheckArtifacts : [],
    run_checks: Array.isArray(toolTelemetry.runChecks) ? toolTelemetry.runChecks : [],
    provider_attempts: attempts,
    termination: termination || metadata.termination || (error ? 'error' : null),
    stopped_because: metadata.stoppedBecause || (error ? error.message : null),
    iterations,
    loop_policy: {
      iteration_limit: iterationLimit,
      decision_steer_iteration: decisionSteerIteration,
      decision_steer_sent_at: decisionSteerSentAt,
    },
    latency_ms: metadata.latencyMs == null ? null : metadata.latencyMs,
    answer_excerpt: answer == null ? null : truncateText(redactSensitiveText(answer), ANSWER_EXCERPT_MAX),
    answer_full: answer == null ? null : redactSensitiveText(answer),
    error: error ? {
      name: error.name || 'Error',
      message: error.message || String(error),
    } : null,
    run_tokens: accounting.seat_tokens,
    run_cost: accounting.seat_cost,
  });
  return sanitizeForLedger({
    ...entry,
    ...rollingCostReceipt({ repoRoot, entry }),
  });
}

function [REDACTED]({
  repoRoot,
  runId,
  startedAt,
  finishedAt = new Date(),
  result,
  attempts = [],
} = {}) {
  const startedIso = isoTimestamp(startedAt || finishedAt);
  const finishedIso = isoTimestamp(finishedAt);
  const repoState = readRepoState(repoRoot);
  const accounting = sumSeatAccounting([{ id: 'provider_preflight', attempts }]);
  const entry = sanitizeForLedger({
    schema_version: 2,
    receipt_type: 'provider_preflight',
    run_id: runId,
    created_at: finishedIso,
    started_at: startedIso,
    branch: repoState.branch,
    head_sha: repoState.head_sha,
    dirty_status_summary: repoState.dirty_status_summary,
    verdict: result && result.ok === true ? 'provider_preflight_pass' : 'provider_preflight_failed',
    challenger_ready: result && result.challengerReady === true,
    tie_breaker_ready: result && result.tieBreakerReady === true,
    provider_attempts: attempts,
    run_tokens: accounting.run_tokens,
    run_cost: accounting.run_cost,
    checks: result && Array.isArray(result.checks) ? result.checks : [],
    repo_adjudication: { status: 'pending', authority: 'live_repo_required' },
  });
  return sanitizeForLedger({
    ...entry,
    ...rollingCostReceipt({
      repoRoot,
      entry,
    }),
  });
}

function countLines(absPath) {
  if (!fs.existsSync(absPath)) return 0;
  const text = fs.readFileSync(absPath, 'utf8');
  if (!text) return 0;
  return text.endsWith('\n') ? text.split('\n').length - 1 : text.split('\n').length;
}

function writeRunLedgerEntry({
  repoRoot,
  entry,
  now = new Date(),
} = {}) {
  if (!repoRoot) throw new Error('repoRoot is required');
  if (!entry || typeof entry !== 'object') throw new Error('ledger entry is required');

  const createdAt = isoTimestamp(entry.created_at || now);
  const day = createdAt.slice(0, 10);
  const relDir = RUN_LEDGER_DIR;
  const absDir = path.join(repoRoot, relDir);
  const relPath = path.join(relDir, `${day}.jsonl`).replace(/\\/g, '/');
  const absPath = path.join(repoRoot, relPath);
  fs.mkdirSync(absDir, { recursive: true });

  const lineNumber = countLines(absPath) + 1;
  const line = `${JSON.stringify(sanitizeForLedger({ ...entry, created_at: createdAt }))}\n`;
  fs.appendFileSync(absPath, line, 'utf8');

  return {
    path: relPath,
    citation: `${relPath}:${lineNumber}`,
    line: lineNumber,
  };
}

module.exports = {
  DEFAULT_RUN_LEDGER_DIR,
  RUN_LEDGER_DIR,
  RAW_PROVIDER_DIR,
  createRawRunId,
  writeRawProviderOutput,
  [REDACTED],
  extractClaimedFileCitations,
  parseSelfReport,
  seatReceiptFields,
  rollingCostReceipt,
  buildPromptProvenance,
  buildRunLedgerEntry,
  buildDirectQuestionLedgerEntry,
  [REDACTED],
  classifyMercuryVerdict,
  resultHasToolFailure,
  autoBlastRadiusFailed,
  collectReviewQuarantines,
  redactSensitiveText,
  sanitizeForLedger,
  writeRunLedgerEntry,
};

