function parseGitNameList(output) {
  return output
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
}

function gitNameList(repoRoot, args) {
  const output = execFileSync('git', args, {
    cwd: repoRoot,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
    maxBuffer: 16 * 1024 * 1024,
  });
  return parseGitNameList(output);
}

function selectCurrentChangeNames({ cached = [], working = [], untracked = [] } = {}) {
  return [...new Set([...cached, ...working, ...untracked])].sort();
}

function currentChangedFiles(repoRoot = config.REPO_ROOT) {
  return selectCurrentChangeNames({
    cached: gitNameList(repoRoot, ['diff', '--name-only', '--cached']),
    working: gitNameList(repoRoot, ['diff', '--name-only']),
    untracked: gitNameList(repoRoot, ['ls-files', '--others', '--exclude-standard', '--', ...UNTRACKED_SERENA_SOURCE_PATHS]),
  });
}

function currentChangeDiff(repoRoot = config.REPO_ROOT, changedFiles = null) {
  const scopedFiles = Array.isArray(changedFiles)
    ? changedFiles.filter(file => typeof file === 'string' && file)
    : null;
  if (scopedFiles && scopedFiles.length === 0) return '';
  const targets = scopedFiles || currentChangedFiles(repoRoot);
  if (targets.length === 0) return '';
  // Match the reviewed WORKTREE bytes, including staged + unstaged changes
  // and new source. The corpus already owns Git preimage/error handling.
  const corpus = collectExplicitTargetCorpus({ repoRoot, explicitPaths: targets });
  return { diff: corpus.artifacts.filter(artifact => artifact.kind === 'diff')
    .map(artifact => artifact.content).join('\n'), unresolved: corpus.unresolved };
}

function normalizeRepoRelativePath(repoRoot, relPath) {
  if (!relPath || typeof relPath !== 'string') return null;
  if (relPath.startsWith('/') || relPath.split('/').includes('..')) return null;
  const absPath = path.resolve(repoRoot, relPath);
  const normalizedRoot = path.resolve(repoRoot);
  if (absPath !== normalizedRoot && !absPath.startsWith(`${normalizedRoot}${path.sep}`)) {
    return null;
  }
  return path.relative(normalizedRoot, absPath).replace(/\\/g, '/');
}

function isSerenaSourcePath(relPath) {
  return typeof relPath === 'string'
    && relPath.endsWith('.js')
    && !relPath.endsWith('.bak')
    && !config.isPathIgnoredByMercury(relPath);
}

async function buildCurrentChangeBlastRadius({
  repoRoot = config.REPO_ROOT,
  changedFiles = null,
  currentChangedFilesFn = currentChangedFiles,
  currentDiffFn = currentChangeDiff,
  existsFn = fs.existsSync,
  getBlastRadiusFn = getBlastRadius,
  formatForMercuryFn = formatForMercury,
  findReferencesFn = null,
  scanSymbolsFn = scanSerenaSymbols,
} = {}) {
  let candidates;
  try {
    candidates = changedFiles || currentChangedFilesFn(repoRoot);
  } catch (err) {
    return {
      text: null,
      meta: [],
      errors: [
        {
          file: '<current_changes>',
          error: err.message,
        },
      ],
      source: 'current_changes',
    };
  }
  const normalizedCandidates = [];
  const targetFiles = [];
  const errors = [];
  for (const candidate of candidates) {
    const relPath = normalizeRepoRelativePath(repoRoot, candidate);
    if (!relPath) continue;
    if (config.isPathIgnoredByMercury(relPath)
        || path.posix.basename(relPath) === '.env'
        || path.posix.basename(relPath).startsWith('.env.')) continue;
    normalizedCandidates.push(relPath);
    if (!relPath.endsWith('.js') || relPath.endsWith('.bak')) continue;
    if (!existsFn(path.join(repoRoot, relPath))) {
      errors.push({ file: relPath, error: 'AST scan target is absent from the working tree' });
      continue;
    }
    targetFiles.push(relPath);
  }

  let diff = '';
  let referenceNames = [];
  try {
    const captured = currentDiffFn(repoRoot, normalizedCandidates);
    diff = typeof captured === 'string' ? captured : captured.diff;
    for (const item of captured.unresolved || []) {
      errors.push({ file: item.target, error: item.reason });
    }
    referenceNames = extractDiffReferenceNames(diff);
  } catch (err) {
    errors.push({ file: '<current_diff>', error: err.message });
  }

  const sections = [];
  const expandedSections = [];
  const meta = [];
  let ast = null;
  const syntaxTargets = new Set(targetFiles);
  for (const targetFile of targetFiles) {
    let blastRadius;
    try {
      blastRadius = await getBlastRadiusFn(targetFile);
    } catch (err) {
      errors.push({
        file: targetFile,
        error: err.message,
      });
      continue;
    }
    let formatted;
    try {
      formatted = formatForMercuryFn(blastRadius);
    } catch (err) {
      errors.push({
        file: targetFile,
        error: `format failed: ${err.message}`,
      });
      continue;
    }
    meta.push({
      file: targetFile,
      callerCount: blastRadius.callerCount,
      riskLevel: blastRadius.riskLevel,
      latencyMs: blastRadius.latencyMs,
    });
    for (const caller of blastRadius.callers || []) {
      if (isSerenaSourcePath(caller.source)) syntaxTargets.add(caller.source);
    }
    sections.push(`## ${targetFile}\n${formatted}`);
    expandedSections.push({ kind: 'blast_radius', target: targetFile, content: formatted });
  }

  const referenceScans = [];
  for (const name of referenceNames) {
    if (typeof findReferencesFn !== 'function') {
      errors.push({ symbol: name, error: 'find_references adapter unavailable' });
      continue;
    }
    try {
      const result = await findReferencesFn(name);
      if (result && result.error) {
        errors.push({ symbol: name, error: result.error });
      } else {
        for (const match of result.matches || []) {
          if (isSerenaSourcePath(match.file)) syntaxTargets.add(match.file);
        }
        referenceScans.push({
          symbol: name,
          source: result && result.source || null,
          precision: result && result.precision || null,
          total: result && Number.isInteger(result.total) ? result.total : null,
          truncated: !!(result && result.truncated),
        });
        sections.push(`## find_references ${name}\n${JSON.stringify(result)}`);
        expandedSections.push({ kind: 'find_references', target: name, content: JSON.stringify(result, null, 2) });
      }
    } catch (err) {
      errors.push({ symbol: name, error: err.message });
    }
  }

  // Parse the complete discovered blast radius after collecting every lexical
  // candidate, not just the first match or every unrelated file in the repo.
  if (syntaxTargets.size > 0) {
    try {
      const scope = [...syntaxTargets].sort();
      const scan = scanSymbolsFn(repoRoot, { scope });
      const names = new Set(referenceNames);
      ast = {
        source: 'serena_symbol_scanner', precision: 'ast_syntax', scope,
        filesScanned: scan.filesScanned, filesParsed: scan.filesParsed,
        parsers: scan.parsers, fileReceipts: scan.fileReceipts, errors: scan.errors,
        functionScopes: scan.functionScopes,
        referenceNames,
        references: scan.propertyRefs.filter(row => names.has(row.property)),
        callers: scan.methodCalls.filter(row => names.has(row.method)),
        limitations: [
          'Scope: selected JS, direct file-import callers and all returned lexical config-name candidates.',
          'Property/method syntax candidates, not proof of receiver identity or dynamic alias/data flow.',
          'Regex/import candidates remain separate evidence; no whole-repository semantic completeness claim.',
        ],
      };
      errors.push(...scan.errors);
      const parsed = new Set(scan.fileReceipts.map(receipt => receipt.file));
      for (const file of scope) {
        if (!parsed.has(file)) errors.push({ file, error: '[REDACTED]' });
      }
      sections.push(`## PARSER CAPTURE\n${JSON.stringify(ast)}`);
      expandedSections.push({ kind: 'ast', target: '<discovered_syntax>', content: JSON.stringify(ast, null, 2) });
    } catch (error) {
      errors.push({ file: '<discovered_syntax>', error: error.message });
    }
  }

  sections.unshift([
    '## CURRENT CHANGE CANDIDATE SET',
    `Changed files: ${normalizedCandidates.length}`,
    ...normalizedCandidates.map(file => `- ${file}`),
    `Touched env/config names: ${referenceNames.length}`,
    ...referenceNames.map(name => `- ${name}`),
  ].join('\n'));
  expandedSections.unshift({ kind: 'candidate_set', target: '<current_changes>', content: sections[0] });

  return {
    text: sections.length > 0 ? sections.join('\n\n') : null,
    expandedSections,
    meta,
    ast,
    errors,
    changedFiles: normalizedCandidates,
    changedFileCount: normalizedCandidates.length,
    diff,
    referenceNames,
    referenceScans,
    source: 'current_changes',
  };
}

function reviewerAbsence(error) {
  const message = String(error && error.message || error || '');
  if (/quota|rate.?limit|HTTP 402|HTTP 429|usage.limit/i.test(message)) return 'quota_or_rate_limit';
  if (/auth|credential|api key|HTTP 401|HTTP 403/i.test(message)) return 'reviewer_credentials_absent';
  return 'reviewer_answer_absent';
}

function priorPanelResult(query, outputs) {
  const successful = [...outputs.values()].filter(output => output && output.answer);
  return {
    answer: successful.length > 0
      ? successful.map(output => `[${output.id}]\n${output.answer}`).join('\n\n')
      : `No prior reviewer output. Independently review the original query:\n${query}`,
    termination: successful.length > 0 ? 'answer_given' : 'not_selected',
    iterations: 0,
    toolTelemetry: null,
    answerQuality: { flags: [], evidence: [] },
    panelSourceLabel: 'Prior selected reviewer evidence',
    panelSourcePath: 'panel://prior-reviewer-evidence',
  };
}

function finalizeMercuryEvidenceResult(result) {
  // Same explicit-field contract as Astra and Kimi. Never infer a verdict
  // from successful transport, a prose conclusion, or a partial tool loop.
  if (!result.parsed && result.termination === 'answer_given') {
    const parsed = parseAdversarialReviewAnswer(result.answer);
    if (parsed.verdict !== 'unknown') result.parsed = parsed;
  }
  return result;
}

function panelSeatMetadata(id, output, {
  autoBlastRadius = null,
  evidenceSources = [],
  inheritedEvidenceBasis = [],
  inputDependencies = [],
} = {}) {
  const attempts = id === 'mercury'
    ? (output.providerAttempts || [])
    : (output.attempts || (output.stageReceipt ? [output.stageReceipt] : []));
  const appliedModels = attempts.flatMap(attempt => attempt.applied_models || (attempt.applied_model ? [attempt.applied_model] : []));
  const identityConflict = attempts.some(attempt => attempt.identity_posture && attempt.identity_posture.status === 'identity_conflict');
  const fallbackTransitions = attempts.flatMap(attempt => attempt.model_transitions || []);
  const directEvidenceBasis = positiveEvidenceBasis({
    toolTelemetry: output.toolTelemetry || {},
    autoBlastRadius: id === 'mercury' ? autoBlastRadius : null,
    evidenceSources,
  });
  const evidenceBasis = [...new Set([...directEvidenceBasis, ...inheritedEvidenceBasis])];
  return {
    answer: output.answer || null,
    parsed: output.parsed || null,
    reasoning: output.parsed && output.parsed.citedReasoning || null,
    stageReceipt: output.stageReceipt || null,
    inputReceipt: output.inputProvenance || null,
    providerRawReceipts: attempts.map(attempt => attempt.raw_output).filter(Boolean),
    providerAttempts: attempts,
    provider: output.provider || (attempts[attempts.length - 1] && attempts[attempts.length - 1].requested_provider) || null,
    requestedModel: output.model || (attempts[attempts.length - 1] && attempts[attempts.length - 1].requested_model) || null,
    appliedModels: [...new Set(appliedModels)],
    fallbackTransitions,
    unavailable: false,
    failed: false,
    identityConflict,
    verdict: structuredPanelVerdict(output.parsed),
    doctrineReview: output.doctrineReview || null,
    evidenceBasis,
    evidenceChecksPassed: evidenceBasis.length > 0
      && !identityConflict
      && !(output.quarantines || []).some(quarantine => quarantine && quarantine.load_bearing === true),
    effectiveIdentityFingerprint: effectiveIdentityFingerprint(id, attempts),
    inputDependencies,
  };
}

function recomputePanelSeatFromRecheck(seat, recheck, { evidenceSources = [] } = {}) {
  const evidenceBasis = positiveEvidenceBasis({
    toolTelemetry: recheck.toolTelemetry || {},
    evidenceSources,
  });
  const doctrineReview = recheck.doctrineReview || null;
  return {
    ...seat,
    answer: recheck.answer || null,
    parsed: recheck.parsed || null,
    reasoning: recheck.parsed && recheck.parsed.citedReasoning || null,
    inputReceipt: recheck.inputProvenance || null,
    providerAttempts: Array.isArray(recheck.providerAttempts) ? recheck.providerAttempts : [],
    verdict: structuredPanelVerdict(recheck.parsed),
    doctrineReview,
    evidenceBasis,
    evidenceChecksPassed: evidenceBasis.length > 0
      && seat.identityConflict !== true
      && !(recheck.quarantines || []).some(quarantine => quarantine && quarantine.load_bearing === true),
    evaluationHistory: [
      ...(Array.isArray(seat.evaluationHistory) ? seat.evaluationHistory : []),
      {
        phase: 'pre_recheck',
        answer: seat.answer,
        parsed: seat.parsed,
        verdict: seat.verdict,
        doctrineReview: seat.doctrineReview,
        evidenceBasis: seat.evidenceBasis,
        evidenceChecksPassed: seat.evidenceChecksPassed,
      },
    ],
    evaluationSource: 'mercury_recheck',
  };
}

function recomputePanelDiagnostics(panelRun) {
  const diagnostics = summarizePanelDiagnostics(panelRun && panelRun.seats);
  if (panelRun) panelRun.diagnostics = diagnostics;
  return diagnostics;
}

function createProviderAudit(stage, {
  repoRoot = config.REPO_ROOT,
  rawRunId,
  pricingCatalog = config.PROVIDER_PRICING,
  writeRaw = writeRawProviderOutput,
} = {}) {
  return {
    stage,
    attempts: [],
    record(metadata = {}, context = {}) {
      const attempt = this.attempts.length + 1;
      const rawOutput = writeRaw({
        repoRoot,
        runId: rawRunId,
        stage: this.stage,
        attempt,
        bytes: metadata.rawResponse || Buffer.alloc(0),
      });
      const requestedProvider = metadata.provider || config.MERCURY_LLM_PROVIDER;
      const requestedModel = metadata.requestedModel || config.MERCURY_LLM_MODEL;
      const accounting = accountProviderAttempt(metadata, {
        provider: requestedProvider,
        model: requestedModel,
        pricingCatalog,
      });
      return {
        attempt,
        stage: this.stage,
        status: context.status,
        retry: context.retry,
        requested_provider: requestedProvider,
        requested_model: requestedModel,
        applied_model: metadata.appliedModel || null,
        started_at: metadata.startedAt || null,
        finished_at: metadata.finishedAt || null,
        latency_ms: metadata.latencyMs == null ? null : metadata.latencyMs,
        status_code: metadata.statusCode == null ? null : metadata.statusCode,
        termination: metadata.termination || null,
        stopped_because: redactSensitiveText(
          metadata.stoppedBecause && metadata.stoppedBecause !== 'provider_stop_reason_absent'
            ? metadata.stoppedBecause
            : responseStopReason({
              termination: metadata.termination,
              statusCode: metadata.statusCode,
              providerError: context.error,
            })
        ),
        parse_status: metadata.parseStatus || null,
        tokens: accounting.tokens,
        usage_absence: accounting.usage_absence,
        cost: accounting.cost,
        cost_absence: accounting.cost_absence,
        identity_posture: metadata.identityPosture || metadata.identity_posture || (
          metadata.appliedModel ? {
            status: 'provider_attested_response',
            authority: 'full',
            requested_model: metadata.requestedModel || null,
            applied_models: [metadata.appliedModel],
          } : null
        ),
        executable_trust: metadata.executableTrust || metadata.executable_trust || null,
        raw_output: rawOutput,
        error: context.error || null,
        repo_adjudication: { status: 'pending', authority: 'live_repo_required' },
      };
    },
  };
}

function runAlertReasons(entry = {}) {
  const reasons = [];
  const panel = entry.reviewer_panel;
  const failedSeats = panel && Array.isArray(panel.seats)
    ? panel.seats.filter(seat => seat.status === 'failed').map(seat => seat.id)
    : [];
  if (failedSeats.length > 0) reasons.push(`seat_failed:${failedSeats.join(',')}`);
  return reasons;
}

async function notifyRunAlerts(entry, { notify = sendMaxPriorityNtfy } = {}) {
  const reasons = runAlertReasons(entry);
  if (reasons.length === 0) return { status: 'not_required', priority: 'max', reasons: [] };
  try {
    const notification = await notify({
      title: 'Mercury bridge run requires operator attention',
      body: `${reasons.join('; ')}; run=${entry.run_id || 'unknown'}; the runner remains nonblocking`,
    });
    return { ...notification, reasons };
  } catch (error) {
    return {
      status: 'failed',
      priority: 'max',
      absence: 'ntfy_delivery_failed',
      error: redactSensitiveText(error && error.message ? error.message : String(error)),
      reasons,
    };
  }
}

// ─────────────────────────────────────────────────────────────
// Agentic mode — hybrid retrieval (current semantic-only) + ReAct loop
// ─────────────────────────────────────────────────────────────

async function runAgentic(query, opts) {
  const startedAt = new Date();
  const rawRunId = createRawRunId(startedAt);
  const reviewerSelection = opts.reviewerSelection || await resolveReviewerSelection({
    explicit: opts.reviewersExplicit ? opts.reviewers : null,
    interactive: false,
    defaultReviewers: reviewModeRequested(opts)
      ? REVIEWER_REGISTRY.map(reviewer => reviewer.id)
      : ['mercury'],
  });
  const providerAuditFactory = stage => createProviderAudit(stage, {
    repoRoot: config.REPO_ROOT,
    rawRunId,
  });
  const providerAudit = providerAuditFactory('mercury');
  const persistReviewRaw = (stage, attempt, bytes) => writeRawProviderOutput({
    repoRoot: config.REPO_ROOT,
    runId: rawRunId,
    stage,
    attempt,
    bytes,
  });
  const verbose = !opts.quiet;
  const requestedMaxIterations = opts.maxIterations == null
    ? null
    : optionalPositiveInteger(opts.maxIterations, '--max-iterations');
  const maxIterations = opts.noTools === true ? 1 : requestedMaxIterations;
  const maxTokens = configExactInteger(opts.maxTokens, config.AGENTIC_MAX_TOKENS, '--max-tokens');
  const pinnedReviewRequested = opts.reviewRef !== undefined || opts.reviewBase !== undefined;
  const explicitTargetReview = pinnedReviewRequested || (Array.isArray(opts.changePaths) && opts.changePaths.length > 0);
  let explicitChangePaths = Array.isArray(opts.changePaths) && opts.changePaths.length > 0 ? normalizeExplicitPaths(opts.changePaths) : null;
  const reviewIntent = opts.reviewIntent || 'adversarial';
  let mercuryQuery = buildMercuryIntentPrompt(query, reviewIntent);
  let evidenceSources = [];
  let evidenceQuarantines = [];
  let inputProvenance = buildAttestedPromptProvenance(mercuryQuery, evidenceSources);

  // Route the query unless caller has overridden
  const route = routeQuery(query);
  const mode = opts.retrievalMode || route.mode;
  const boostType = opts.boostType != null ? opts.boostType : route.boostType;
  const explicitTopK = optionalNonNegativeInteger(opts.topK, '--top-k');

  // Starter context policy: respect --top-k if caller set it, otherwise route decides
  let topK;
  if (explicitTopK != null) {
    topK = explicitTopK;
  } else if (route.starterContextPolicy === 'skip') {
    topK = 0;
  } else {
    topK = config.RETRIEVE_TOP_K;
  }

  // 1. Retrieve starter context from the existing indexed corpus
  const store = explicitTargetReview ? null : new MongoStore();
  let storeConnected = false;
  let autoBlastRadius = null;
  let explicitReviewCorpus = null;
  let explicitContinuationFactory = null;
  let starterContext = [];
  let indexFreshness = null;

  try {
    const reviewView = pinnedReviewRequested ? captureGitReviewView({
      repoRoot: config.REPO_ROOT, ref: opts.reviewRef, baseRef: opts.reviewBase,
      outputDir: path.join(config.REPO_ROOT, RUN_LEDGER_DIR, rawRunId),
    }) : null;
    const reviewRoot = reviewView ? reviewView.sourceRoot : config.REPO_ROOT;
    evidenceSources = resolveEvidenceSources({
      repoRoot: reviewRoot, query, descriptors: opts.evidenceSources || [],
    });
    evidenceQuarantines = await notifyReviewQuarantines(evidenceSources.quarantines);
    inputProvenance = buildAttestedPromptProvenance(mercuryQuery, evidenceSources);
    const reviewGit = reviewView ? (_root, args) => execFileSync('git', args, {
      cwd: config.REPO_ROOT, env: { ...process.env, GIT_OPTIONAL_LOCKS: '0', GIT_LITERAL_PATHSPECS: '1' },
      maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'],
    }) : null;
    const reviewDiff = reviewView ? (_root, paths) => reviewGit(null,
      ['diff', '--binary', '--no-ext-diff', reviewView.baseTree, reviewView.tree, '--', ...paths]).toString() : null;
    if (reviewView) {
      if (!explicitChangePaths) explicitChangePaths = normalizeExplicitPaths(reviewGit(null,
        ['diff', '--name-only', '-z', reviewView.baseTree, reviewView.tree]).toString().split('\0').filter(Boolean));
      query = `Review source tree: ${reviewView.tree}; comparison baseline: ${reviewView.baseTree}. File, search and AST tools read the captured tree; Git history reads identify their requested ref explicitly.\n\n${query}`;
      mercuryQuery = buildMercuryIntentPrompt(query, reviewIntent);
      inputProvenance = buildAttestedPromptProvenance(mercuryQuery, evidenceSources);
      if (verbose) console.log(`[MERCURY-BRIDGE] Pinned source tree ${reviewView.tree}, baseline ${reviewView.baseTree}, ${reviewView.files.length} captured files`);
    }
    if (store) {
    await store.connect();
    storeConnected = true;

    const health = await store.healthCheck();
    if (!health.ok) {
      throw new Error(`MongoDB health check failed: ${health.error}`);
    }
    if (health.chunkCount === 0) {
      throw new Error('No chunks in index. Run indexer.js first.');
    }

    // Index freshness for the receipt: a stale RAG index silently narrows
    // coverage routing. Surface it on every dispatch, not on archaeology.
    try {
      const latestStats = await store.stats.find().sort({ _id: -1 }).limit(1).toArray();
      if (latestStats.length > 0) {
        const statsDoc = latestStats[0];
        indexFreshness = {
          indexed_at: (statsDoc.index_freshness && statsDoc.index_freshness.indexed_at) || statsDoc.run_at || null,
          index_head_sha: (statsDoc.index_freshness && statsDoc.index_freshness.head_sha) || null,
          files_walked: statsDoc.files_walked == null ? null : statsDoc.files_walked,
          chunks: statsDoc.chunks_embedded == null ? statsDoc.chunks_produced : statsDoc.chunks_embedded,
        };
      }
    } catch (freshnessErr) {
      indexFreshness = { error: freshnessErr.message };
    }

    if (verbose) {
      console.log(`[MERCURY-BRIDGE] Index contains ${health.chunkCount} chunks`);
      console.log(`[MERCURY-BRIDGE] Query router: type=${route.queryType} mode=${mode} boost=${boostType || 'none'} top-k=${topK}`);
      console.log(`[MERCURY-BRIDGE] Rationale: ${route.rationale}`);
    }

    if (topK > 0) {
      if (verbose) console.log('[MERCURY-BRIDGE] Embedding query for starter context...');
      const queryEmbedding = await embedText(query);
      starterContext = await retrieveTopK(store, queryEmbedding, topK, query, {
        retrievalMode: mode,
        boostType: boostType,
      });
    } else {
      if (verbose) console.log('[MERCURY-BRIDGE] Starter context: skipped (router policy=skip)');
    }

    if (verbose) {
      console.log(`[MERCURY-BRIDGE] Starter context: ${starterContext.length} chunks`);
      starterContext.forEach((c, idx) => {
        console.log(`  ${idx + 1}. ${c.file_path}:${c.start_line}-${c.end_line} ` +
          `(${c.kind}: ${c.name || 'unnamed'}) sim=${c.similarity.toFixed(3)}`);
      });
    }

    }
    if (explicitTargetReview && verbose) {
      console.log('[MERCURY-BRIDGE] Explicit target ingestion: source snapshots; no indexed retrieval or trace-memory access');
    }

    // 2. Investigation trace memory — retrieve prior hint if available
    let traceHintText = null;
    let traceUsed = null;
    if (store && config.TRACE_MEMORY_ENABLED) {
      await ensureTraceIndexes(store);
      await evictStaleTraces({ store, verbose });

      const traceResult = await retrieveSimilarTrace({ store, query });
      if (traceResult) {
        traceHintText = formatTraceAsHint(traceResult);
        traceUsed = traceResult.trace;
        if (verbose) {
          console.log(`[MERCURY-BRIDGE] Prior trace hint found (similarity: ${traceResult.similarity.toFixed(2)}, ${traceResult.trace.iterations} iters, used ${traceResult.trace.usage_count}x)`);
        }
      } else if (verbose) {
        console.log('[MERCURY-BRIDGE] No similar prior trace found');
      }
    }

    // 3. Build the tool adapter with both repo access and mongo (for get_chunk)
    const toolAdapter = createToolAdapter({
      repoRoot: reviewRoot,
      gitRepoRoot: config.REPO_ROOT,
      reviewSource: reviewView && { tree: reviewView.tree, baseTree: reviewView.baseTree },
      mongoStore: store,
    });

    if (verbose) {
      console.log(`[MERCURY-BRIDGE] Tool adapter ready. Tools: ${Object.keys(toolAdapter.tools).join(', ')}`);
    }

    let blastRadius = explicitTargetReview ? null : (opts.blastRadius || null);
    const hostEvidenceSources = [];
    if (!blastRadius) {
      autoBlastRadius = await buildCurrentChangeBlastRadius({
        repoRoot: reviewRoot,
        changedFiles: explicitChangePaths,
        findReferencesFn: symbol => toolAdapter.captureReferences(symbol),
        ...(reviewView ? {
          currentDiffFn: reviewDiff,
          getBlastRadiusFn: file => getBlastRadius(file, { repoRoot: reviewRoot }),
        } : {}),
      });
      autoBlastRadius.reviewTarget = {
        source: explicitTargetReview ? 'explicit_change_paths' : 'current_changes',
        paths: autoBlastRadius.changedFiles || [],
        ...(reviewView ? { tree: reviewView.tree, baseTree: reviewView.baseTree,
          manifest: path.relative(config.REPO_ROOT, reviewView.manifestPath), manifestSha256: reviewView.manifestSha256 } : {}),
      };
      if (explicitTargetReview) {
        const unresolvedEvidence = [
          ...(autoBlastRadius.errors || []).map(entry => ({
            target: entry.file || entry.symbol || '<evidence_expansion>',
            scope: 'evidence_expansion', reason: entry.error, load_bearing: true,
          })),
          ...(autoBlastRadius.referenceScans || []).filter(entry => entry.truncated).map(entry => ({
            target: entry.symbol, scope: 'evidence_expansion',
            reason: 'reference_scan_truncated', load_bearing: true,
          })),
        ];
        explicitReviewCorpus = buildExplicitReviewCorpus({
          repoRoot: reviewRoot,
          targetPaths: explicitChangePaths,
          expandedEvidenceSections: autoBlastRadius.expandedSections || [],
          unresolvedEvidence,
          sourceShardMaxBytes: config.[REDACTED],
          requestMaxBytes: config.[REDACTED],
          isPolicyExcluded: file => config.isPathIgnoredByMercury(file),
          ...(reviewView ? { git: reviewGit, currentDiffFn: reviewDiff,
            sourceRef: reviewView.tree, baseRef: reviewView.baseTree, diffRef: `${reviewView.baseTree}..${reviewView.tree}` } : {}),
        });
      }
      if (autoBlastRadius.expandedSections && autoBlastRadius.expandedSections.length > 0) {
        let artifact = null;
        try {
          autoBlastRadius.evidenceBundle = [REDACTED]({
            repoRoot: config.REPO_ROOT,
            runId: rawRunId,
            sections: explicitReviewCorpus ? explicitReviewCorpus.artifacts : autoBlastRadius.expandedSections,
            reviewManifest: explicitReviewCorpus ? {
              corpus_sha256: explicitReviewCorpus.corpus_sha256,
              targets: explicitReviewCorpus.targets,
              unresolved: explicitReviewCorpus.unresolved,
              units: explicitReviewCorpus.unit_manifest,
              excluded_targets: explicitReviewCorpus.excluded_targets,
            } : null,
            now: startedAt,
          });
          artifact = fs.readFileSync(path.join(config.REPO_ROOT, autoBlastRadius.evidenceBundle.path));
        } catch (error) {
          const quarantine = reviewQuarantine({
            unit: 'evidence_artifact',
            name: `current_change_evidence:${rawRunId}`,
            absence: 'scan_artifact_unavailable',
            error,
          });
          const detail = redactSensitiveText(error && error.message ? error.message : String(error));
          autoBlastRadius.errors.push({
            file: autoBlastRadius.evidenceBundle?.path || `<current_change_evidence:${rawRunId}>`,
            error: detail,
          });
          autoBlastRadius.text += `\n\nEVIDENCE ABSENCE: scan_artifact_unavailable (${rawRunId}). Artifact write/read failed: ${detail}. No current-change artifact excerpts delivered; partial files are preserved. This absence is retained in the exit receipt; review continues.`;
          console.error(`[MERCURY-BRIDGE] Current-change evidence artifact quarantined: ${detail}; recorded in exit receipt; review continues`);
          evidenceQuarantines.push(...await notifyReviewQuarantines([quarantine]));
        }
        if (artifact !== null) {
          const bundle = autoBlastRadius.evidenceBundle;
          const artifactLines = artifact.toString('utf8').split('\n');
          if (artifactLines.at(-1) === '') artifactLines.pop();
          // Use the existing attested-excerpt contract for every part of the
          // captured scan. A reviewer without repo tools needs the bytes, not
          // just a path or Mercury's description of what the scan found.
          for (let start = 0; start < artifactLines.length; start += 150) {
            const excerpt = artifactLines.slice(start, start + 150).join('\n');
            hostEvidenceSources.push({
              path: bundle.path, line_start: start + 1,
              line_end: Math.min(start + 150, artifactLines.length),
              artifact_sha256: crypto.createHash('sha256').update(artifact).digest('hex'),
              artifact_bytes: artifact.length,
              excerpt_sha256: crypto.createHash('sha256').update(excerpt).digest('hex'),
              excerpt_bytes: Buffer.byteLength(excerpt, 'utf8'), excerpt,
            });
          }
          autoBlastRadius.text += [
            '', '', '## CAPTURED CURRENT-CHANGE EVIDENCE ARTIFACT',
            `Artifact: ${bundle.path}`,
            `Artifact SHA-256: ${bundle.sha256}`,
            `Artifact bytes: ${bundle.bytes}; sections: ${bundle.section_count}`,
            `Section manifest: ${bundle.manifest_path}`,
            'The manifest identifies exact section ranges for open_file. Storage is not proof of review or complete dependency discovery.',
          ].join('\n');
        }
      }
      blastRadius = autoBlastRadius.text;
      if (verbose) {
        if (autoBlastRadius.meta.length > 0) {
          console.log(`[MERCURY-BRIDGE] Serena current-change blast radius: ${autoBlastRadius.meta.length} file(s)`);
          autoBlastRadius.meta.forEach((meta) => {
            console.log(`  ${meta.file}: ${meta.callerCount} caller(s), risk=${meta.riskLevel}, ${meta.latencyMs}ms`);
          });
        } else {
          console.log('[MERCURY-BRIDGE] Serena current-change blast radius: no changed JS files to scan');
        }
        if (autoBlastRadius.errors.length > 0) {
          console.log(`[MERCURY-BRIDGE] Serena current-change blast radius unavailable for ${autoBlastRadius.errors.length} file(s)`);
          autoBlastRadius.errors.forEach((entry) => {
            console.log(`  ${entry.file}: ${entry.error}`);
          });
        }
      }
    }

    // 4. Dispatch exactly the selected registry seats in declared order.
    let client = null;
    let mercuryResult = null;
    let astraReview = null;
    let kimiReview = null;
    const outputs = new Map();
    const panelRun = await runReviewerPanel({
      selected: reviewerSelection.selected,
      isHardStop: isHardReviewBoundaryError,
      runSeat: async (reviewer, priorSeats) => {
        if (verbose) console.log(`[MERCURY-BRIDGE] Starting reviewer seat: ${reviewer.label}`);
        if (reviewer.id === 'mercury') {
          if (!client) {
            client = createMercuryLlmClient({ systemPrompt: config.AGENTIC_SYSTEM_PROMPT });
            await client.initialize();
          }
          const prior = priorPanelResult(query, outputs);
          const userQuery = outputs.size === 0
            ? mercuryQuery
            : `${mercuryQuery}\n\nPrior selected reviewer outputs to investigate:\n${prior.answer}`;
          const t0 = Date.now();
          const seatResult = explicitReviewCorpus ? await runExplicitTargetReview({
            client, corpus: explicitReviewCorpus, query: userQuery,
            continueWithTools: reviewView && reviewIntent === 'adversarial' && opts.noTools !== true
              ? (explicitReviewContract, remainingCalls) => {
                explicitContinuationFactory = previous => explicitReviewContract.fresh(previous);
                return runReactLoop({
                  client, toolAdapter, userQuery, maxTokens, maxIterations: remainingCalls, verbose,
                  explicitReviewContract,
                  providerAudit: providerAuditFactory('[REDACTED]'),
                });
              } : null,
            syntaxContext: autoBlastRadius && autoBlastRadius.ast,
            maxRequestBytes: config.[REDACTED],
            maxTokens, maxCalls: maxIterations,
            providerAuditFactory, verbose, isHardStop: isHardReviewBoundaryError,
            evidenceAbsences: evidenceQuarantines,
          }) : await runReactLoop({
            client, toolAdapter, userQuery, starterContext, traceHint: traceHintText,
            blastRadius, maxIterations, maxTokens, verbose, providerAudit,
            attack: opts.attack === true,
            noTools: opts.noTools === true,
          });
          mercuryResult = seatResult;
          mercuryResult.totalLatencyMs = Date.now() - t0;
          // A failed attempt still owns its tools, history and provider receipt.
          // Preserve them before answer qualification; failure is not non-selection.
          ensureReviewerAnswer(mercuryResult, 'mercury');
          finalizeMercuryEvidenceResult(mercuryResult);
          mercuryResult.doctrineReview = assessDoctrineReview({
            answer: mercuryResult.answer,
            candidateSet: mercuryResult.candidateSet,
            changedFiles: autoBlastRadius ? autoBlastRadius.changedFiles : [],
            diff: autoBlastRadius ? autoBlastRadius.diff : '',
            telemetry: mercuryResult.toolTelemetry,
            autoScan: autoBlastRadius,
            evidenceSources,
            reviewerId: 'mercury',
            answerQuality: mercuryResult.answerQuality,
          });
          outputs.set('mercury', { id: 'mercury', ...mercuryResult });
          const metadata = panelSeatMetadata('mercury', mercuryResult, {
            autoBlastRadius,
            evidenceSources,
            inputDependencies: priorSeats.map(seat => ({
              sequence: seat.sequence,
              id: seat.id,
              answerSha256: seat.answer ? crypto.createHash('sha256').update(seat.answer).digest('hex') : null,
              evidenceQualified: seat.evidenceChecksPassed === true,
            })),
          });
          return metadata;
        }

        if (reviewer.id === 'astra') {
          const prior = mercuryResult || priorPanelResult(query, outputs);
          astraReview = await runAstraAdversarialReview({
            reviewRoot, query, mercuryResult: prior, reviewIntent,
            persistRaw: persistReviewRaw, evidenceSources, hostEvidenceSources,
          });
          if (astraReview.ok !== true) {
            const error = new Error(astraReview.error && astraReview.error.message || 'Astra answer absent');
            error.absence = reviewerAbsence(error);
            error.reviewFailure = astraReview;
            throw error;
          }
          astraReview.mode = reviewModeRequested(opts) || 'adversarial_review';
          astraReview.doctrineReview = assessDoctrineReview({
            answer: astraReview.answer,
            changedFiles: autoBlastRadius ? autoBlastRadius.changedFiles : [],
            diff: autoBlastRadius ? autoBlastRadius.diff : '',
            telemetry: mercuryResult ? mercuryResult.toolTelemetry : {},
            autoScan: autoBlastRadius,
            evidenceSources,
            reviewerId: 'astra',
            answerQuality: mercuryResult ? mercuryResult.answerQuality : {},
          });
          astraReview.quarantines = await notifyReviewQuarantines(astraReview.quarantines || []);
          // A rejected primary answer still needs the source checks Astra
          // requested. Preserve its failed evidence status; do not skip repair.
          if (mercuryResult && typeof mercuryResult.answer === 'string' && mercuryResult.answer.trim()
              && kimiTieBreakerRequired(astraReview, reviewIntent)) {
            const recheckPrompts = buildMercuryRecheckPrompts({
              originalQuery: query,
              mercuryAnswer: mercuryResult.answer,
              astraAnswer: astraReview.answer,
              parsedReview: astraReview.parsed,
              evidenceSources,
              filesMechanicallyOpened: Array.isArray(mercuryResult.toolTelemetry && mercuryResult.toolTelemetry.filesOpened)
                ? mercuryResult.toolTelemetry.filesOpened
                : [],
              claimedFileCitations: extractClaimedFileCitations(mercuryResult.answer),
              candidateSet: mercuryResult.candidateSet,
            }).slice(0, config.ADVERSARIAL_REVIEW_MAX_RECHECKS);
            astraReview.recheckPrompts = recheckPrompts;
            astraReview.recheckPrompt = recheckPrompts[0] || null;
            const recheckRun = await runReviewRechecks({
              prompts: recheckPrompts, client, toolAdapter, starterContext, blastRadius,
              maxIterations, maxTokens, verbose, evidenceSources, createProviderAudit: providerAuditFactory,
              attack: opts.attack === true,
              noTools: opts.noTools === true,
              explicitContinuationFactory: explicitContinuationFactory
                ? rechecks => explicitContinuationFactory({ ...mercuryResult, continuationRechecks: [...rechecks] }) : null,
              claimInventory: mercuryResult.candidateSet?.claimInventory || [],
              claimSourceEvidence: (mercuryResult.shardedReview?.claim_inventory || []).flatMap(target => target.source_evidence || []),
            });
            astraReview.rechecks = recheckRun.rechecks;
            astraReview.recheck = astraReview.rechecks[0] || null;
            astraReview.quarantines.push(...recheckRun.quarantines);
            mercuryResult.candidateSet = mergeCandidateSetRechecks(
              mercuryResult.candidateSet,
              astraReview.rechecks
            );
            for (const recheck of astraReview.rechecks) {
              recheck.doctrineReview = assessDoctrineReview({
                answer: recheck.answer,
                candidateSet: recheck.candidateSet,
                changedFiles: autoBlastRadius ? autoBlastRadius.changedFiles : [],
                diff: autoBlastRadius ? autoBlastRadius.diff : '',
                telemetry: recheck.toolTelemetry,
                autoScan: autoBlastRadius,
                evidenceSources,
                reviewerId: 'mercury',
                answerQuality: recheck.answerQuality,
              });
            }
          }
          outputs.set('astra', { id: 'astra', ...astraReview });
          const qualifiedPrior = priorSeats.filter(seat => seat.evidenceChecksPassed === true);
          const metadata = panelSeatMetadata('astra', astraReview, {
            evidenceSources: [...evidenceSources, ...hostEvidenceSources],
            inheritedEvidenceBasis: qualifiedPrior.map(seat => `qualified_prior_seat:${seat.sequence}:${seat.id}`),
            inputDependencies: priorSeats.map(seat => ({
              sequence: seat.sequence,
              id: seat.id,
              answerSha256: seat.answer ? crypto.createHash('sha256').update(seat.answer).digest('hex') : null,
              evidenceQualified: seat.evidenceChecksPassed === true,
            })),
          });
          // Rechecks retain Mercury's provenance in astraReview.rechecks;
          // they must not replace Astra's independent answer or evidence.
          return metadata;
        }

        const prior = mercuryResult || priorPanelResult(query, outputs);
        const earlierAstraSeat = priorSeats.find(seat => seat.id === 'astra' && seat.status === 'succeeded');
        const review = earlierAstraSeat ? astraReview : {
          answer: priorPanelResult(query, outputs).answer,
          parsed: { verdict: 'not_selected', blocking: false },
          rechecks: [],
          recheckPrompts: [],
          panelSourceLabel: 'Earlier selected reviewer evidence (no prior Astra seat)',
          panelSourcePath: 'panel://prior-reviewer-evidence',
        };
        kimiReview = await runKimiFinalAdjudication({
          query, mercuryResult: prior, review,
          persistRaw: persistReviewRaw, evidenceSources, hostEvidenceSources,
        });
        kimiReview.doctrineReview = assessDoctrineReview({
          answer: kimiReview.answer,
          changedFiles: autoBlastRadius ? autoBlastRadius.changedFiles : [],
          diff: autoBlastRadius ? autoBlastRadius.diff : '',
          telemetry: mercuryResult ? mercuryResult.toolTelemetry : {},
          autoScan: autoBlastRadius,
          evidenceSources,
          reviewerId: 'kimi',
          answerQuality: mercuryResult ? mercuryResult.answerQuality : {},
        });
        kimiReview.quarantines = await notifyReviewQuarantines(kimiReview.quarantines || []);
        outputs.set('kimi', { id: 'kimi', ...kimiReview });
        const qualifiedPrior = priorSeats.filter(seat => seat.evidenceChecksPassed === true);
        const metadata = panelSeatMetadata('kimi', kimiReview, {
          evidenceSources: [...evidenceSources, ...hostEvidenceSources],
          inheritedEvidenceBasis: qualifiedPrior.map(seat => `qualified_prior_seat:${seat.sequence}:${seat.id}`),
          inputDependencies: priorSeats.map(seat => ({
            sequence: seat.sequence,
            id: seat.id,
            answerSha256: seat.answer ? crypto.createHash('sha256').update(seat.answer).digest('hex') : null,
            evidenceQualified: seat.evidenceChecksPassed === true,
          })),
        });
        return metadata;
      },
    });

    const failedQuarantines = [];
    for (const seat of panelRun.seats.filter(seat => seat.status === 'failed')) {
      const failedOutput = seat.error && (seat.error.reviewFailure || seat.error.reviewerResult || (seat.error.stageAttempt ? {
        attempts: Array.isArray(seat.error.reviewerAttempts)
          ? seat.error.reviewerAttempts
          : [seat.error.stageAttempt],
        stageReceipt: seat.error.stageAttempt,
      } : null));
      const failedMetadata = failedOutput
        ? panelSeatMetadata(seat.id, failedOutput)
        : (seat.id === 'mercury' ? panelSeatMetadata('mercury', { providerAttempts: providerAudit.attempts }) : null);
      seat.absence = seat.absence === 'reviewer_answer_absent' ? reviewerAbsence(seat.error) : seat.absence;
      failedQuarantines.push(reviewQuarantine({
        unit: 'reviewer_seat', name: seat.id, absence: seat.absence, error: seat.error,
      }));
      seat.failed = true;
      seat.unavailable = true;
      seat.error = seat.error && seat.error.message ? { name: seat.error.name, message: seat.error.message } : null;
      seat.provider = failedMetadata && failedMetadata.provider || null;
      seat.requestedModel = failedMetadata && failedMetadata.requestedModel || null;
      seat.appliedModels = failedMetadata ? failedMetadata.appliedModels : [];
      seat.fallbackTransitions = failedMetadata ? failedMetadata.fallbackTransitions : [];
      seat.providerAttempts = failedMetadata ? failedMetadata.providerAttempts : [];
      seat.answer = failedMetadata ? failedMetadata.answer : null;
      seat.verdict = null;
      seat.evidenceChecksPassed = false;
    }
    const notifiedFailures = await notifyReviewQuarantines(failedQuarantines);

    let result = mercuryResult;
    if (!result) {
      const firstOutput = reviewerSelection.selected.map(id => outputs.get(id)).find(Boolean);
      result = firstOutput ? {
        answer: firstOutput.answer,
        termination: 'answer_given',
        iterations: 0,
        totalLatencyMs: firstOutput.latencyMs || 0,
        history: [],
        toolTelemetry: { byTool: {}, filesOpened: [], runCheckArtifacts: [], runChecks: [] },
        toolsAvailable: [],
        providerAttempts: [],
        answerQuality: { flags: [], evidence: [] },
      } : {
        answer: 'No selected reviewer produced an answer.',
        termination: 'reviewers_unavailable',
        iterations: 0,
        totalLatencyMs: 0,
        history: [],
        toolTelemetry: { byTool: {}, filesOpened: [], runCheckArtifacts: [], runChecks: [] },
        toolsAvailable: [],
        providerAttempts: [],
        answerQuality: { flags: [], evidence: [] },
      };
    }
    result.evidenceSources = evidenceSources;
    result.reviewQuarantines = [
      ...evidenceQuarantines,
      ...(Array.isArray(result.reviewQuarantines) ? result.reviewQuarantines : []),
      ...notifiedFailures,
    ];
    result.inputProvenance = inputProvenance;
    result.reviewerPanel = { ...reviewerSelection, ...panelRun };
    // Keep diagnostics for the expanded evidence without rewriting any seat.
    if (mercuryResult && mercuryResult.candidateSet?.candidateSources?.length > 1) {
      const latestDoctrine = assessDoctrineReview({
        answer: mercuryResult.answer, candidateSet: mercuryResult.candidateSet,
        changedFiles: autoBlastRadius?.changedFiles || [], diff: autoBlastRadius?.diff || '',
        telemetry: mercuryResult.toolTelemetry, autoScan: autoBlastRadius,
        evidenceSources, reviewerId: 'mercury', answerQuality: mercuryResult.answerQuality,
      });
      const mercurySeat = panelRun.seats.find(seat => seat.id === 'mercury');
      if (mercurySeat) mercurySeat.recheckDiagnostics = latestDoctrine;
    }
    if (autoBlastRadius) result.serenaBlastRadius = autoBlastRadius;
    if (astraReview) {
      const astraSeat = panelRun.seats.find(seat => seat.id === 'astra' && seat.status === 'succeeded');
      const kimiSeat = panelRun.seats.find(seat => seat.id === 'kimi' && seat.status === 'succeeded');
      if (canAttachFinalReview(astraSeat, kimiSeat)) {
        astraReview.finalReview = kimiReview;
        result.reviewerPanel.diagnostics = recomputePanelDiagnostics(panelRun);
      }
      result.adversarialReview = astraReview;
      result.consensus = astraReview;
      result.adversarialReviewPacket = formatAdversarialReviewPacket({
        originalQuery: query, mercuryResult: mercuryResult || priorPanelResult(query, outputs),
        review: astraReview, panel: result.reviewerPanel, reviewIntent,
      });
    }

    // 6. Mark trace as used if we injected one
    if (mercuryResult && traceUsed && result.termination === 'answer_given') {
      await markTraceUsed({ store, traceId: traceUsed._id });
    }

    // 7. Capture successful investigation trace (with dedup + quality)
    if (store && mercuryResult && config.TRACE_MEMORY_ENABLED && result.termination === 'answer_given') {
      const toolCallSequence = (result.history || []).map(h => ({
        name: h.toolName,
        args: h.toolArgs,
        result_summary: JSON.stringify(h.toolResult || {}).slice(0, 500),
      }));

      const captureResult = await captureTrace({
        store,
        query,
        toolCallSequence,
        finalAnswer: result.answer,
        captureRequested: opts.captureTrace === true,
        metadata: {
          iterations: result.iterations,
          latencyMs: result.totalLatencyMs,
          termination: result.termination,
          captureRequested: opts.captureTrace === true,
        },
      });

      if (verbose) {
        if (captureResult.captured) {
          console.log(`[MERCURY-BRIDGE] Trace ${captureResult.action} (quality=${(captureResult.new_quality || captureResult.quality || 0).toFixed(1)})`);
        } else {
          const reason = captureResult.reason || captureResult.action;
          console.log(`[MERCURY-BRIDGE] Trace not captured: ${reason}`);
          if (reason === 'manual_capture_not_requested') {
            console.log('[MERCURY-BRIDGE] Manual capture mode: rerun with --capture-trace only if this answer should teach trace memory.');
          }
        }
      }
    }

    const ledgerEntry = buildRunLedgerEntry({
      repoRoot: config.REPO_ROOT,
      query,
      opts: {
        ...opts,
        maxIterations,
        maxTokens,
        decisionSteerIteration: config.AGENTIC_DECISION_STEER_ITERATION,
      },
      result,
      startedAt,
      finishedAt: new Date(),
      autoBlastRadius,
      evidenceSources,
      inputProvenance,
    });
    ledgerEntry.alert = await notifyRunAlerts(ledgerEntry);
    result.runLedger = writeRunLedgerEntry({
      repoRoot: config.REPO_ROOT,
      entry: ledgerEntry,
    });
    // Keep the full ledger entry on the result: the stdout receipt must carry
    // everything the ledger knows (verdict, quality evidence, tool failures) —
    // the ledger dir is gitignored and bridge-blocked for session reads.
    result.runLedgerEntry = ledgerEntry;
    result.indexFreshness = indexFreshness;

    return result;

  } catch (err) {
    const ledgerEntry = buildRunLedgerEntry({
      repoRoot: config.REPO_ROOT,
      query,
      opts: {
        ...opts,
        maxIterations,
        maxTokens,
        decisionSteerIteration: config.AGENTIC_DECISION_STEER_ITERATION,
      },
      error: err,
      startedAt,
      finishedAt: new Date(),
      autoBlastRadius,
      evidenceSources,
      inputProvenance,
    });
    ledgerEntry.alert = await notifyRunAlerts(ledgerEntry);
    err.mercuryRunLedger = writeRunLedgerEntry({
      repoRoot: config.REPO_ROOT,
      entry: ledgerEntry,
    });
    throw err;
  } finally {
    if (storeConnected) {
      await store.disconnect();
    }
  }
}

// ─────────────────────────────────────────────────────────────
// Dispatch receipt — everything the run ledger knows, in stdout,
// every dispatch, quiet mode included. The ledger dir is gitignored
// and bridge-blocked; a receipt that hides in it is not a receipt.
// ─────────────────────────────────────────────────────────────

function printDispatchReceipt(result) {
  const entry = result.runLedgerEntry || {};
  const formatCost = (cost) => (
    cost && Number.isFinite(cost.amount)
      ? `${cost.currency || 'USD'} ${cost.amount.toFixed(6)}${cost.complete === false ? ' (partial)' : ''}`
      : 'unknown'
  );
  console.log('');
  console.log('═══ RECEIPT ═══');
  console.log(`verdict:         ${entry.verdict || 'unknown'}`);
  console.log(`cost:            run=${formatCost(entry.run_cost)} | today=${formatCost(entry.daily_cost_total)} | month=${formatCost(entry.monthly_cost_total)}`);
  const panel = entry.reviewer_panel;
  if (panel) {
    console.log(`reviewers:       ${panel.selected.join(',')} (${panel.source})`);
    console.log(`unselected:      ${panel.unselected.length > 0 ? panel.unselected.join(',') : 'none'}`);
    console.log(`reported by:     ${panel.reported_decision.reviewer || 'none'}; model report, not host certification`);
    console.log(`panel findings:  ${panel.diagnostics.issues.join(',') || 'none'}; verdict_labels_match=${panel.diagnostics.verdictLabelsMatch ? 'yes' : 'no'} (not semantic consensus)`);
    for (const seat of panel.seats) {
      const selfReportAbsence = Array.isArray(seat.named_absences) && seat.named_absences.includes('self_report_absent')
        ? ' self_report_absent'
        : '';
      console.log(`  - ${seat.id}: ${seat.status} provider=${seat.provider || 'unavailable'} models=${(seat.appliedModels || []).join(',') || 'none'} stopped=${seat.stopped_because || 'unknown'}${seat.absence ? ` absence=${seat.absence}` : ''}${selfReportAbsence}`);
      console.log(`    reported verdict=${seat.parsed?.verdict || 'absent'} evidence=${seat.evidenceChecksPassed === true ? 'observed' : 'missing_or_failed'} identity=${seat.identityConflict ? 'conflict' : 'see_provider_receipt'}`);
      console.log(`    review findings: ${(seat.doctrineReview?.namedAbsences || []).join(',') || 'none'}${seat.recheckDiagnostics ? `; recheck=${seat.recheckDiagnostics.namedAbsences.join(',') || 'none'}` : ''}`);
    }
  }

  for (const [index, recheck] of (entry.adversarial_review?.rechecks || []).entries()) {
    console.log(`recheck ${index + 1}:       ${recheck.termination || 'unknown'}; findings=${(recheck.doctrine_review?.namedAbsences || []).join(',') || 'none'}`);
  }
  for (const gap of entry.review_quarantines || []) {
    console.log(`review failure:  ${gap.unit}:${gap.name} ${gap.absence}`);
  }

  const doctrine = entry.doctrine_review;
  if (doctrine) {
    console.log(`review coverage: candidate=${doctrine.candidateSet ? `${doctrine.candidateSet.examined}/${doctrine.candidateSet.total}` : 'absent'}`);
    console.log(`named absences:  ${(doctrine.namedAbsences || []).join(',') || 'none'}`);
    console.log(`named breaks:    ${(doctrine.namedBreaks || []).join(',') || 'none'}`);
  }

  const qualityFlags = Array.isArray(entry.answer_quality) ? entry.answer_quality : [];
  const qualityEvidence = Array.isArray(entry.answer_quality_evidence) && entry.answer_quality_evidence.length > 0
    ? entry.answer_quality_evidence
    : qualityFlags.map((flag) => ({ flag, evidence: null }));
  if (qualityFlags.length === 0) {
    console.log('quality flags:   none');
  } else {
    for (const item of qualityEvidence) {
      console.log(`quality flag:    ${item.flag} — ${item.evidence ? `"${item.evidence}"` : '(no quote captured)'}`);
    }
  }

  const runChecks = Array.isArray(entry.run_checks) ? entry.run_checks : [];
  const assertsWithoutExecution = runChecks.length === 0
    && qualityFlags.some((flag) => /unsupported|uncited/.test(flag));
  console.log(`run checks:      ${runChecks.length} executed${assertsWithoutExecution ? ' — answer asserts outcomes with no execution backing' : ''}`);

  const toolsInvoked = Array.isArray(entry.tools_invoked) ? entry.tools_invoked : [];
  const failedCalls = [];
  let totalCalls = 0;
  for (const tool of toolsInvoked) {
    totalCalls += tool.calls || 0;
    for (const call of tool.call_details || []) {
      if (call.status === 'failed') {
        const reason = call.result && call.result.error ? call.result.error : 'failed';
        failedCalls.push(`${tool.name}(${JSON.stringify(call.args)}): ${reason}`);
      }
    }
  }
  console.log(`tool failures:   ${failedCalls.length}/${totalCalls}`);
  failedCalls.forEach((line) => console.log(`  - ${line}`));
  if (result.toolTelemetry) {
    console.log(`tool calls:      ${formatToolTelemetry(result.toolTelemetry)}`);
  }

  const sourceRefs = entry.source_refs || {};
  const blastFiles = Array.isArray(sourceRefs.auto_blast_radius_files) ? sourceRefs.auto_blast_radius_files.length : 0;
  const blastErrors = Array.isArray(sourceRefs.auto_blast_radius_errors) ? sourceRefs.auto_blast_radius_errors : [];
  console.log(`blast radius:    ${blastFiles} file(s) scanned, ${blastErrors.length} error(s)`);
  blastErrors.forEach((blastError) => console.log(`  - ${blastError.file}: ${blastError.error}`));
  const bundle = sourceRefs.current_change_evidence_bundle;
  if (bundle) {
    console.log(`AST evidence:    ${bundle.path}`);
    console.log(`evidence hash:   ${bundle.sha256} bytes=${bundle.bytes} sections=${bundle.section_count}`);
    console.log(`section manifest: ${bundle.manifest_path} sha256=${bundle.manifest_sha256}`);
  }

  const candidateSet = entry.candidate_set;
  if (candidateSet) {
    console.log(`candidate set:   iteration=${candidateSet.captured_at_iteration} citations=${candidateSet.claimed_file_citations.length} answer-subset=${candidateSet.answer_citations_subset ? 'yes' : 'no'}`);
  }

  const reviewEntry = entry.adversarial_review;
  if (!reviewEntry) {
    console.log('review layer:    not requested');
  } else if (reviewEntry.ok) {
    console.log(`review layer:    ok — ${reviewEntry.mode || 'adversarial_review'} verdict=${reviewEntry.effective_verdict || 'n/a'}`);
    if (reviewEntry.final_review) {
      const final = reviewEntry.final_review;
      const finalStatus = final.ok ? 'ok' : 'FAILED';
      console.log(`final adjud.:    ${finalStatus} — ${final.mode || 'kimi_final_adjudication'} verdict=${final.effective_verdict || 'n/a'}`);
      const sharedSupport = final.parsed && (final.parsed.consensus || final.parsed.sharedConclusion);
      if (sharedSupport) {
        console.log(`shared support:  ${sharedSupport}`);
      }
      if (final.parsed && final.parsed.contradictions && !/^none\b/i.test(final.parsed.contradictions)) {
        console.log(`contradictions:  ${final.parsed.contradictions}`);
      }
      if (final.parsed && final.parsed.blindSpots && !/^none\b/i.test(final.parsed.blindSpots)) {
        console.log(`blind spots:     ${final.parsed.blindSpots}`);
      }
    }
  } else {
    const reviewError = reviewEntry.error && reviewEntry.error.message
      ? reviewEntry.error.message
      : JSON.stringify(reviewEntry.error);
    console.log(`review layer:    FAILED — ${reviewError}`);
  }

  const selfReportUnits = [
    ['mercury', entry.stages && entry.stages.mercury],
    ['astra', reviewEntry],
    ...((reviewEntry && reviewEntry.rechecks) || []).map((recheck, index) => [`mercury_recheck_${index + 1}`, recheck]),
    ['kimi', reviewEntry && reviewEntry.final_review],
  ];
  for (const [label, unit] of selfReportUnits) {
    if (unit && Array.isArray(unit.named_absences) && unit.named_absences.includes('self_report_absent')) {
      console.log(`self-report:     ${label}=self_report_absent missing=${(unit.self_report_missing_fields || []).join(',') || 'unknown'}`);
    }
  }

  const quarantines = Array.isArray(entry.review_quarantines) ? entry.review_quarantines : [];
  console.log(`quarantines:     ${quarantines.length}`);
  quarantines.forEach((item) => {
    const notification = item.ntfy || {};
    console.log(`  - ${item.unit}:${item.name} absence=${item.absence} load-bearing=${item.load_bearing === true ? 'yes' : 'no'} ntfy=max/${notification.status || 'unrecorded'}`);
    if (notification.absence) console.log(`    notification absence=${notification.absence}`);
  });

  const dirty = String(entry.dirty_status_summary || '').trim();
  console.log(dirty
    ? `tree state:      DIRTY — ${dirty.split('\n').map((line) => line.trim()).join(', ')}`
    : 'tree state:      clean');

  const freshness = result.indexFreshness;
  if (freshness && !freshness.error) {
    const idxSha = String(freshness.index_head_sha || '').slice(0, 8) || 'unknown';
    const headSha = String(entry.head_sha || '').slice(0, 8) || 'unknown';
    const indexedAt = freshness.indexed_at ? new Date(freshness.indexed_at) : null;
    const staleDays = indexedAt && !Number.isNaN(indexedAt.getTime())
      ? Math.floor((Date.now() - indexedAt.getTime()) / 86400000)
      : null;
    const staleLabel = staleDays == null
      ? ''
      : ` (${staleDays}d ${idxSha !== 'unknown' && idxSha === headSha ? 'old, same head' : 'stale'})`;
    console.log(`index freshness: indexed ${freshness.indexed_at || 'unknown'} @ ${idxSha} — HEAD ${headSha}${staleLabel}`);
  } else {
    console.log(`index freshness: unavailable${freshness && freshness.error ? ` (${freshness.error})` : ''}`);
  }

  if (result.runLedger) {
    console.log(`run ledger:      ${result.runLedger.citation}`);
  }
}

