    run_check_artifacts: Array.isArray(telemetry.runCheckArtifacts) ? telemetry.runCheckArtifacts : [],
    run_checks: Array.isArray(telemetry.runChecks) ? telemetry.runChecks : [],
    answer_quality: answerQualityFlags,
    answer_quality_evidence: answerQualityEvidence,
    candidate_set: candidateSet ? {
      coverage: candidateSet.coverage || null,
      claim_inventory: Array.isArray(candidateSet.claimInventory) ? candidateSet.claimInventory : [],
      content: redactSensitiveText(candidateSet.content || ''),
      captured_at_iteration: candidateSet.capturedAtIteration,
      revised_at_iteration: candidateSet.revisedAtIteration || null,
      revisions: candidateSet.revisions || [],
      files_mechanically_opened: Array.isArray(candidateSet.filesMechanicallyOpened)
        ? candidateSet.filesMechanicallyOpened
        : [],
      file_read_receipts: Array.isArray(candidateSet.fileReadReceipts)
        ? candidateSet.fileReadReceipts
        : [],
      claimed_file_citations: Array.isArray(candidateSet.claimedFileCitations)
        ? candidateSet.claimedFileCitations
        : [],
      final_answer_citations: Array.isArray(candidateSet.finalAnswerCitations)
        ? candidateSet.finalAnswerCitations
        : [],
      answer_citations_subset: candidateSet.answerCitationsSubset === true,
      citations_not_in_candidate_set: Array.isArray(candidateSet.citationsNotInCandidateSet)
        ? candidateSet.citationsNotInCandidateSet
        : [],
      candidate_sources: Array.isArray(candidateSet.candidateSources)
        ? candidateSet.candidateSources.map(candidateSourceLedgerReceipt)
        : [],
    } : null,
    review_quarantines: reviewQuarantines,
    sharded_review: shardedReviewLedgerReceipt(result && result.shardedReview),
    review_scope: autoBlastRadius && autoBlastRadius.reviewTarget || null,
    adversarial_review: reviewSummary,
    consensus: reviewSummary,
    reviewer_panel: result && result.reviewerPanel ? panelSeatLedger(result.reviewerPanel, result) : null,
    doctrine_review: result && result.doctrineReview ? result.doctrineReview : null,
    stages: {
      mercury: result ? {
        provider_attempts: Array.isArray(result.providerAttempts) ? result.providerAttempts : [],
        ...seatReceiptFields(
          result.answer ? redactSensitiveText(result.answer) : null,
          Array.isArray(result.providerAttempts) ? result.providerAttempts : [],
          result.termination || null
        ),
        tools_available: Array.isArray(result.toolsAvailable) ? result.toolsAvailable : [],
        tools_invoked: compactToolStats(telemetry),
        files_mechanically_opened: Array.isArray(telemetry.filesOpened) ? telemetry.filesOpened : [],
        repo_adjudication: { status: 'pending', authority: 'live_repo_required' },
      } : null,
      challenger: reviewSummary,
      tie_breaker: reviewSummary && reviewSummary.final_review ? reviewSummary.final_review : null,
    },
    termination: result ? result.termination : null,
    iterations: result ? result.iterations : null,
    latency_ms: result ? result.totalLatencyMs : null,
    verdict,
    error: error ? {
      name: error.name || 'Error',
      message: error.message || String(error),
    } : null,
    answer_excerpt: result && result.answer
      ? truncateText(redactSensitiveText(result.answer), ANSWER_EXCERPT_MAX)
      : null,
    run_tokens: runAccounting.run_tokens,
    run_cost: runAccounting.run_cost,
  });
  return sanitizeForLedger({
    ...entry,
    ...rollingCostReceipt({
      repoRoot,
      entry,
    }),
  });
}

